INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$d5d3ea31$SATQ$, $SATQ$2d43925d-e0c3-44ec-b583-82c5c0d2a74e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;The Yellow Wallpaper&rdquo; is an 1892 short story by Charlotte Perkins Gilman. In the story, the narrator expresses mixed feelings about her surroundings: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;The Yellow Wallpaper&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"c8868907-ffed-4bcc-ac70-ec995fc78fc6","content":"<p>&ldquo;This wallpaper has a kind of sub-pattern in a different shade, a particularly irritating one, for you can only see it in certain lights, and not clearly then.&rdquo;</p>"},{"id":"0b0d4dd4-eb95-4ab8-9cd0-2d9a5a5bbf03","content":"<p>&ldquo;By moonlight&mdash;the moon shines in all night when there is a moon&mdash;I wouldn&rsquo;t know it was the same paper.&rdquo;</p>"},{"id":"c39af3b7-3d2a-4291-bd5c-8883d4ff793e","content":"<p>&ldquo;I&rsquo;m really getting quite fond of the big room, all but that horrid [wall]paper.&rdquo;</p>"},{"id":"d26d88a5-5ba7-4b59-97da-c9f5c1194fa5","content":"<p>&ldquo;The color is repellant, almost revolting; a smouldering, unclean yellow, strangely faded by the slow-turning sunlight.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c39af3b7-3d2a-4291-bd5c-8883d4ff793e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively illustrates the claim that the narrator of "The Yellow Wallpaper" has mixed feelings about her surroundings. She says she is "really getting quite fond of the big room," a positive sentiment, but also describes the room&rsquo;s wallpaper as "horrid," a negative sentiment. Since some of her feelings about her surroundings are positive and others are negative, they are best described as mixed.</p><p>Choice A is incorrect because though the narrator describes the room&rsquo;s wallpaper as "irritating," a negative sentiment, she does not mention a positive sentiment. Thus, the quotation does not effectively illustrate the claim that the narrator has mixed feelings about her surroundings. Choice B is incorrect because it describes how the appearance of the room&rsquo;s wallpaper changes at night but does not mention the narrator&rsquo;s feelings about her surroundings. Choice D is incorrect because though the narrator describes the room&rsquo;s wallpaper as "repellant," a negative sentiment, she does not mention a positive sentiment. Thus, the quotation does not effectively illustrate the claim that the narrator has mixed feelings about her surroundings.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d5d3ea31","external_id":"2d43925d-e0c3-44ec-b583-82c5c0d2a74e","vaultid":null,"uId":"b285adac-a0a6-499e-a7ae-409a68a017c6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>&ldquo;The Yellow Wallpaper&rdquo; is an 1892 short story by Charlotte Perkins Gilman. In the story, the narrator expresses mixed feelings about her surroundings: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;The Yellow Wallpaper&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"c8868907-ffed-4bcc-ac70-ec995fc78fc6","content":"<p>&ldquo;This wallpaper has a kind of sub-pattern in a different shade, a particularly irritating one, for you can only see it in certain lights, and not clearly then.&rdquo;</p>"},{"id":"0b0d4dd4-eb95-4ab8-9cd0-2d9a5a5bbf03","content":"<p>&ldquo;By moonlight&mdash;the moon shines in all night when there is a moon&mdash;I wouldn&rsquo;t know it was the same paper.&rdquo;</p>"},{"id":"c39af3b7-3d2a-4291-bd5c-8883d4ff793e","content":"<p>&ldquo;I&rsquo;m really getting quite fond of the big room, all but that horrid [wall]paper.&rdquo;</p>"},{"id":"d26d88a5-5ba7-4b59-97da-c9f5c1194fa5","content":"<p>&ldquo;The color is repellant, almost revolting; a smouldering, unclean yellow, strangely faded by the slow-turning sunlight.&rdquo;</p>"}],"keys":["c39af3b7-3d2a-4291-bd5c-8883d4ff793e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively illustrates the claim that the narrator of \"The Yellow Wallpaper\" has mixed feelings about her surroundings. She says she is \"really getting quite fond of the big room,\" a positive sentiment, but also describes the room&rsquo;s wallpaper as \"horrid,\" a negative sentiment. Since some of her feelings about her surroundings are positive and others are negative, they are best described as mixed.</p><p>Choice A is incorrect because though the narrator describes the room&rsquo;s wallpaper as \"irritating,\" a negative sentiment, she does not mention a positive sentiment. Thus, the quotation does not effectively illustrate the claim that the narrator has mixed feelings about her surroundings. Choice B is incorrect because it describes how the appearance of the room&rsquo;s wallpaper changes at night but does not mention the narrator&rsquo;s feelings about her surroundings. Choice D is incorrect because though the narrator describes the room&rsquo;s wallpaper as \"repellant,\" a negative sentiment, she does not mention a positive sentiment. Thus, the quotation does not effectively illustrate the claim that the narrator has mixed feelings about her surroundings.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
